package dev.thillainirmal.modelmesh.service;
import dev.thillainirmal.modelmesh.model.*; import org.springframework.stereotype.Service; import java.time.*;
@Service public class ModelExecutionService {private final ModelMeshRouter router;private final ProviderExecutor executor;public ModelExecutionService(ModelMeshRouter router,ProviderExecutor executor){this.router=router;this.executor=executor;}public ExecutionResponse execute(ExecuteRequest request){var route=router.route(request.routeRequest());long start=System.nanoTime();try{var result=executor.execute(route.selected().id(),request.prompt(),request.expectedOutputTokens());return response(route,result,false,start);}catch(RuntimeException primary){if(route.fallback().id().equals(route.selected().id()))throw primary;var result=executor.execute(route.fallback().id(),request.prompt(),request.expectedOutputTokens());return response(route,result,true,start);}}private ExecutionResponse response(RouteDecision route,ProviderExecutor.Result result,boolean fallback,long start){return new ExecutionResponse(fallback?route.fallback().id():route.selected().id(),result.model(),result.content(),fallback,Duration.ofNanos(System.nanoTime()-start).toMillis(),route);}}
